insert into public.questions (prompt,choices,correct_index,explanation_id,explanation_en,level,skill,is_published) select v.prompt,v.choices,v.correct_index,v.explanation_id,v.explanation_en,v.level::public.jlpt_level,v.skill::public.content_skill,v.is_published from (values ('「学生」の読み方はどれですか？','["がくせい","がっこう","せんせい","かいしゃ"]'::jsonb,0,'学生は「がくせい」と読みます。','学生 is read がくせい.','N5','vocabulary',true),('「食べる」の意味はどれですか？','["minum","makan","pergi","melihat"]'::jsonb,1,'食べるは「makan」です。','食べる means eat.','N5','vocabulary',true),('「日」の意味として正しいものはどれですか？','["bulan","hari/matahari","air","gunung"]'::jsonb,1,'日には day/sun の意味があります。','日 can mean day or sun.','N5','kanji',true),('「これは本です。」の意味はどれですか？','["Ini buku.","Itu guru.","Saya pelajar.","Ini sekolah."]'::jsonb,0,'これは本です。＝ Ini buku.','これは本です。 means This is a book.','N5','grammar',true),('Tempat melakukan aktivitas biasanya ditandai dengan partikel apa?','["を","で","へ","が"]'::jsonb,1,'で menandai tempat berlangsungnya aktivitas.','で marks the location of an activity.','N5','grammar',true),('「明日」の読み方はどれですか？','["きょう","きのう","あした","あさ"]'::jsonb,2,'明日は「あした」と読みます。','明日 is read あした.','N5','vocabulary',true),('「先生」の意味はどれですか？','["student","teacher","friend","company"]'::jsonb,1,'先生は teacher です。','先生 means teacher.','N5','vocabulary',true),('「水」の読み方はどれですか？','["みず","ひ","つち","やま"]'::jsonb,0,'水の訓読みは「みず」です。','水 is read みず in this basic N5 use.','N5','kanji',true)) v(prompt,choices,correct_index,explanation_id,explanation_en,level,skill,is_published) where not exists (select 1 from public.questions q where q.prompt=v.prompt and q.level=v.level::public.jlpt_level);
insert into public.reading_passages (title,level,body_jp,translation_id,translation_en,estimated_minutes,sort_order,is_published) select v.title,v.level::public.jlpt_level,v.body_jp,v.translation_id,v.translation_en,v.estimated_minutes,v.sort_order,v.is_published from (values ('自己紹介','N5','わたしはエノです。インドネシア人です。日本語を勉強しています。毎日、五つの漢字を勉強します。','Saya Eno. Saya orang Indonesia. Saya sedang belajar bahasa Jepang. Setiap hari saya belajar lima kanji.','I am Eno. I am Indonesian. I study Japanese. Every day I study five kanji.',2,1,true),('学校の一日','N5','毎朝、七時に起きます。学校へ行きます。学校で日本語を勉強します。午後四時に家へ帰ります。','Setiap pagi saya bangun jam tujuh. Saya pergi ke sekolah. Di sekolah saya belajar bahasa Jepang. Jam empat sore saya pulang.','Every morning I get up at seven. I go to school. I study Japanese at school. I go home at four in the afternoon.',3,2,true)) v(title,level,body_jp,translation_id,translation_en,estimated_minutes,sort_order,is_published) where not exists (select 1 from public.reading_passages r where r.title=v.title and r.level=v.level::public.jlpt_level);
insert into public.listening_items (title,level,transcript_jp,translation_id,duration_seconds,sort_order,is_published) select v.title,v.level::public.jlpt_level,v.transcript_jp,v.translation_id,v.duration_seconds,v.sort_order,v.is_published from (values ('あいさつ N5','N5','おはようございます。こんにちは。こんばんは。','Sapaan dasar: selamat pagi, siang, dan malam.',30,1,true),('自己紹介 N5','N5','はじめまして。わたしはエノです。インドネシア人です。よろしくお願いします。','Perkenalan diri sederhana.',35,2,true)) v(title,level,transcript_jp,translation_id,duration_seconds,sort_order,is_published) where not exists (select 1 from public.listening_items l where l.title=v.title and l.level=v.level::public.jlpt_level);
